    $candidateWorkColumns=db_rows("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='SafetyVote_Candidates' AND COLUMN_NAME IN ('SourceType','SourceCampaignID','SourceCandidateID')");
    $versionColumns=db_rows("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='SafetyVote_CampaignVersions'");$columnMap=[];foreach($versionColumns as$column)$columnMap[strtolower((string)$column['COLUMN_NAME'])]=true;
    $media=['ParentVersionID','ChangeReason'];$live=['LiveLeaderboardEnabled','LiveLeaderboardTopN','LiveLeaderboardScoreMode','LiveLeaderboardVisibility','LiveLeaderboardRefreshSeconds','LiveLeaderboardPrivacyThreshold'];$attempts=['MaxParticipationAttempts'];$eligibility=['EligibilityEnrollmentMode','EligibilityEnrollmentUpdatedAt','EligibilityEnrollmentUpdatedBy'];
    $shapeByVersion=[
