        '2026-10-16-participation-attempts-r1'=>array_merge($media,$live,$attempts),
        '2026-10-16-campaign-governance-r1'=>array_merge($media,$live,$attempts),
        '2026-10-20-eligibility-amendments-r1'=>array_merge($media,$live,$attempts,$eligibility),
        '2026-10-24-question-images-r1'=>array_merge($media,$live,$attempts,$eligibility),
        '2026-10-24-candidate-submission-gallery-r1'=>array_merge($media,$live,$attempts,$eligibility),
        '2026-10-25-official-topn-next-cycle-r1'=>array_merge($media,$live,$attempts,$eligibility,['OfficialResultTopN']),
        '2026-10-25-result-release-policy-r1'=>array_merge($media,$live,$attempts,$eligibility,['OfficialResultTopN','ResultReleasePolicy']),
        '2026-10-25-jury-work-items-atomic-media-r1'=>array_merge($media,$live,$attempts,$eligibility,['OfficialResultTopN','ResultReleasePolicy','WorkSource']),
    ];
    $enabled=($map['module_enabled']??'0')==='1';$schema=$map['schema_version']??'';$requiredColumns=$shapeByVersion[$schema]??[];$missingColumns=array_values(array_filter($requiredColumns,static function($name)use($columnMap){return!isset($columnMap[strtolower($name)]);}));
    $schemaReady=in_array($schema,['2026-10-15-live-results-r1','2026-10-16-participation-attempts-r1','2026-10-16-campaign-governance-r1','2026-10-20-eligibility-amendments-r1','2026-10-24-question-images-r1','2026-10-24-candidate-submission-gallery-r1','2026-10-25-official-topn-next-cycle-r1','2026-10-25-result-release-policy-r1','2026-10-25-jury-work-items-atomic-media-r1'],true)||(!$enabled&&in_array($schema,[SV_SCHEMA_VERSION,'2026-10-08-phase6-r1','2026-10-08-phase7-r1','2026-10-09-phase10.4-r1'],true));
    $questionImagesReady=count($imageColumns)===2;$capabilityReady=$schema!=='2026-10-24-question-images-r1'||$questionImagesReady;$galleryShapeReady=$schema!=='2026-10-24-candidate-submission-gallery-r1'||($questionImagesReady&&$galleryReady);
