function sv_has_permission(array$user,string$permission): bool {if(sv_role($user)==='ADMIN')return true;$override=db_row('SELECT granted FROM admin_userpermissions WHERE employee_id=? AND permission=? LIMIT 1',[sv_actor($user),$permission]);if($override)return(int)$override['granted']===1;$role=db_row('SELECT granted FROM admin_rolepermissions WHERE UPPER(role)=? AND permission=? LIMIT 1',[sv_role($user),$permission]);if($role&&(int)$role['granted']===1)return true;$admin=db_row('SELECT granted FROM admin_userpermissions WHERE employee_id=? AND permission=? LIMIT 1',[sv_actor($user),'SAFETY_VOTE_ADMIN']);return$admin&&(int)$admin['granted']===1;}
