function sv_can_read_private_file(array$user,array$file): bool {if(sv_role($user)==='ADMIN'||sv_has_permission($user,'SAFETY_VOTE_MANAGE'))return true;try{$publicWork=db_row("SELECT g.id FROM SafetyVote_GalleryItems g JOIN SafetyVote_Candidates w ON w.id=g.OwnerID AND g.OwnerType='candidate' JOIN SafetyVote_CampaignVersions v ON v.id=w.CampaignVersionID JOIN SafetyVote_Campaigns c ON c.id=v.CampaignID AND c.CurrentVersionID=v.id WHERE g.FileID=? AND g.Status='Active' AND w.Status IN ('Active','Finalist') AND v.CampaignType='jury_scoring' AND c.Status IN ('Scheduled','Open','Closed','Certified','Published') AND c.IsHidden=0 AND c.IsTest=0 LIMIT 1",[(int)$file['id']]);if($publicWork)return true;}catch(Throwable$error){if(!in_array((string)$error->getCode(),['42S02','42S22'],true))throw$error;}if(strtolower((string)($file['FilePurpose']??''))==='candidate_gallery'){try{$assigned=db_row("SELECT g.id FROM SafetyVote_GalleryItems g JOIN SafetyVote_Candidates c ON c.id=g.OwnerID AND g.OwnerType='candidate' JOIN SafetyVote_JuryAssignments a ON a.CampaignVersionID=c.CampaignVersionID AND a.JurorEmployeeID=? AND a.Status IN ('Draft','Submitted') AND (a.CandidateID IS NULL OR a.CandidateID=c.id) WHERE g.FileID=? AND g.Status='Active' LIMIT 1",[sv_actor($user),(int)$file['id']]);if($assigned)return true;}catch(Throwable$error){if(!in_array((string)$error->getCode(),['42S02','42S22'],true))throw$error;}}if(in_array(strtolower((string)($file['FilePurpose']??'')),['promotion_desktop','promotion_mobile','promotion_library'],true)){try{$visible=db_row("SELECT c.id FROM SafetyVote_Campaigns c WHERE c.id=? AND c.Status<>'Voided' AND c.IsHidden=0 AND c.IsTest=0 LIMIT 1",[(int)$file['CampaignID']]);if($visible)return true;}catch(Throwable$error){if(!in_array((string)$error->getCode(),['42S02','42S22'],true))throw$error;}}$restricted=!empty($file['SubmissionID'])||!empty($file['QuestionID'])||in_array(strtolower((string)($file['FilePurpose']??'')),['submission','answer'],true);if($restricted){if((string)($file['UploadedBy']??'')===sv_actor($user))return true;if(!empty($file['SubmissionID'])&&sv_has_permission($user,'SAFETY_VOTE_SUBMISSION_REVIEW'))return true;if(!empty($file['QuestionID'])&&sv_has_permission($user,'SAFETY_VOTE_EXPORT'))return true;return false;}$scope=db_row("SELECT e.id FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id JOIN SafetyVote_Campaigns c ON c.CurrentVersionID=s.CampaignVersionID WHERE c.id=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[(int)$file['CampaignID'],sv_actor($user)]);return(bool)$scope;}
function sv_rehearsal_projection(array$row):array{return['employeeId'=>(string)$row['employeeId'],'departmentId'=>$row['departmentId']??null,'safetyUnitId'=>$row['safetyUnitId']??null,'positionId'=>$row['positionId']??null,'role'=>$row['role']??'','team'=>$row['team']??'','accountReady'=>(bool)$row['accountReady']];}
function sv_eligibility_diff(array$baseline,array$current,int$limit=100):array{$before=[];$after=[];foreach($baseline as$row)$before[(string)$row['employeeId']]=sv_rehearsal_projection($row);foreach($current as$row)$after[(string)$row['employeeId']]=sv_rehearsal_projection($row);$added=[];$removed=[];$changed=[];foreach($after as$id=>$row)if(!isset($before[$id]))$added[]=$id;elseif($row!==$before[$id])$changed[]=$id;foreach($before as$id=>$row)if(!isset($after[$id]))$removed[]=$id;sort($added,SORT_STRING);sort($removed,SORT_STRING);sort($changed,SORT_STRING);return['addedCount'=>count($added),'removedCount'=>count($removed),'changedCount'=>count($changed),'unchangedCount'=>max(0,count($after)-count($added)-count($changed)),'addedEmployeeIds'=>array_slice($added,0,$limit),'removedEmployeeIds'=>array_slice($removed,0,$limit),'changedEmployeeIds'=>array_slice($changed,0,$limit),'truncated'=>count($added)>$limit||count($removed)>$limit||count($changed)>$limit];}
function sv_audit(array$user,string$action,string$targetType,string$targetId,string$detail,array$metadata=[],?int$campaignId=null,?int$versionId=null): void {try{db_execute('INSERT INTO SafetyVote_AuditLogs(CampaignID,CampaignVersionID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,BoundedDetail,MetadataJson,IPAddress,UserAgent) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$campaignId,$versionId,sv_actor($user),sv_role($user),$action,$targetType,$targetId,200,sv_clean($detail,1000)?:null,json_encode($metadata,JSON_UNESCAPED_UNICODE),(string)($_SERVER['REMOTE_ADDR']??''),mb_substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,255)]);}catch(Throwable$error){error_log('[safety-vote] audit failed: '.$error->getMessage());}}

function sv_reconcile_due_campaign_closures(): array {
    $pdo=db();
    $changed=[];
    $pdo->beginTransaction();
    try{
        $rows=db_rows("SELECT c.id,c.CurrentVersionID,c.CampaignCode,v.CloseAt FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.Status='Open' AND COALESCE(v.CloseAt,c.ScheduledCloseAt) IS NOT NULL AND COALESCE(v.CloseAt,c.ScheduledCloseAt)<=NOW() ORDER BY c.id LIMIT 100 FOR UPDATE");
        $campaignUpdate=$pdo->prepare("UPDATE SafetyVote_Campaigns SET Status='Closed',ClosedAt=COALESCE(ClosedAt,NOW()),UpdatedBy='SYSTEM_SCHEDULE',RowVersion=RowVersion+1 WHERE id=? AND Status='Open'");
        $versionUpdate=$pdo->prepare("UPDATE SafetyVote_CampaignVersions SET Status='Closed',UpdatedBy='SYSTEM_SCHEDULE',RowVersion=RowVersion+1 WHERE id=? AND Status IN ('Frozen','Open')");
        $audit=$pdo->prepare("INSERT INTO SafetyVote_AuditLogs(CampaignID,CampaignVersionID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,BoundedDetail,MetadataJson) VALUES(?,?,'SYSTEM_SCHEDULE','SYSTEM','SAFETY_VOTE_SCHEDULE_CLOSE','SafetyVote_Campaign',?,200,'Scheduled close reconciled automatically',?)");
        foreach($rows as$row){
            $campaignUpdate->execute([(int)$row['id']]);
            if($campaignUpdate->rowCount()!==1)continue;
            $versionUpdate->execute([(int)$row['CurrentVersionID']]);
            $metadata=json_encode(['campaignCode'=>$row['CampaignCode'],'closeAt'=>$row['CloseAt'],'trigger'=>'authenticated_request_guard'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
            $audit->execute([(int)$row['id'],(int)$row['CurrentVersionID'],(string)$row['id'],$metadata]);
            $changed[]=['id'=>(int)$row['id'],'versionId'=>(int)$row['CurrentVersionID'],'status'=>'Closed'];
        }
        $pdo->commit();
        if(function_exists('sv4_finalize_closed_popular_vote'))foreach($changed as&$item){try{$item['resultFinalization']=sv4_finalize_closed_popular_vote((int)$item['id'],'SYSTEM_SCHEDULE','authenticated_request_guard');}catch(Throwable$finalizationError){$item['resultFinalization']=['status'=>'failed','code'=>'RESULT_FINALIZATION_FAILED'];error_log('[safety-vote] automatic result finalization failed for campaign '.(int)$item['id'].': '.$finalizationError->getMessage());}}unset($item);
        return$changed;
    }catch(Throwable$error){
        if($pdo->inTransaction())$pdo->rollBack();
        throw$error;
    }
}
