function sv_master_projection(): array { $employees=db_rows('SELECT EmployeeID,EmployeeName,Department,Unit,Team,Position,Role,Password,MustChangePassword FROM employees ORDER BY EmployeeID');$departments=db_rows('SELECT id,Name,Status,is_safety_core FROM master_departments ORDER BY Name');$units=db_rows('SELECT id,name,department_id,short_code,sort_order FROM master_safetyunits ORDER BY department_id,sort_order,name');$positions=db_rows('SELECT id,Name FROM master_positions ORDER BY Name');$index=onboarding_build_master_index(['departments'=>$departments,'units'=>$units]);$key=fn($value)=>onboarding_normalize_name($value);$dept=[];$unit=[];$pos=[];foreach($departments as$row)$dept[$key($row['Name'])]=$row;foreach($units as$row)$unit[(string)$row['department_id']."\0".$key($row['name'])]=$row;foreach($positions as$row)$pos[$key($row['Name'])]=$row;$rows=[];foreach($employees as$row){$d=$dept[$key($row['Department'])]??null;$u=$d?($unit[(string)$d['id']."\0".$key($row['Unit'])]??null):null;$p=$pos[$key($row['Position'])]??null;try{$status=onboarding_resolve_with_index($row,$index);}catch(OnboardingResolutionException$error){$status=$error->reason;}$warnings=[];if(!$d)$warnings[]='DEPARTMENT_UNRESOLVED';if($d&&!$u&&array_filter($units,fn($x)=>(int)$x['department_id']===(int)$d['id']))$warnings[]='SAFETY_UNIT_UNRESOLVED';if(!$p)$warnings[]='POSITION_UNRESOLVED';$rows[]=['employeeId'=>(string)$row['EmployeeID'],'employeeName'=>(string)($row['EmployeeName']??''),'departmentId'=>$d?(int)$d['id']:null,'departmentName'=>(string)($row['Department']??''),'safetyUnitId'=>$u?(int)$u['id']:null,'safetyUnitName'=>(string)($row['Unit']??''),'positionId'=>$p?(int)$p['id']:null,'positionName'=>(string)($row['Position']??''),'role'=>(string)($row['Role']??''),'team'=>(string)($row['Team']??''),'masterPresent'=>true,'accountReady'=>$status===ONBOARDING_READY,'onboardingStatus'=>$status,'masterWarnings'=>$warnings];}return['employees'=>$rows,'departments'=>$departments,'units'=>$units,'positions'=>$positions]; }
function sv_private_dir(): string {$dir=dirname(__DIR__).DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'safety-vote';if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Unable to prepare Safety Vote private storage.');return$dir;}
function sv_file_mime(string$file): ?string {$head=(string)file_get_contents($file,false,null,0,16);if(strlen($head)>=3&&ord($head[0])===0xff&&ord($head[1])===0xd8&&ord($head[2])===0xff)return'image/jpeg';if(substr($head,0,8)==="\x89PNG\r\n\x1a\n")return'image/png';if(substr($head,0,4)==='RIFF'&&substr($head,8,4)==='WEBP')return'image/webp';if(substr($head,0,5)==='%PDF-')return'application/pdf';return null;}
function sv_private_file_disk(array$file):?string{$dir=sv_private_dir();$stored=(string)($file['StoredName']??'');if($stored!==basename($stored))return null;$disk=$dir.DIRECTORY_SEPARATOR.$stored;if(is_file($disk))return$disk;$sha=strtolower((string)($file['ContentSha256']??''));if(!preg_match('/^[a-f0-9]{64}$/',$sha))return null;$aliases=db_rows("SELECT StoredName FROM SafetyVote_Files WHERE Status='Active' AND ContentSha256=? AND MimeType=? AND FileSize=? AND id<>? ORDER BY id",[$sha,(string)$file['MimeType'],(int)$file['FileSize'],(int)$file['id']]);foreach($aliases as$alias){$candidate=$dir.DIRECTORY_SEPARATOR.basename((string)$alias['StoredName']);if(is_file($candidate))return$candidate;}return null;}
function sv_clone_option_images(PDO$pdo,int$sourceVersionId,int$targetCampaignId,int$targetVersionId,string$uploadedBy):int{
    $files=db_rows("SELECT DISTINCT f.* FROM SafetyVote_Options o JOIN SafetyVote_Questions q ON q.id=o.QuestionID JOIN SafetyVote_Files f ON f.id=o.FileID AND f.Status='Active' WHERE q.CampaignVersionID=? AND q.Status='Active' AND o.Status='Active' AND o.FileID IS NOT NULL ORDER BY f.id",[$sourceVersionId]);
    $copied=[];$insert=$pdo->prepare('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?)');
    foreach($files as$file){
        $disk=sv_private_file_disk($file);
        if(!$disk||sv_file_mime($disk)!==(string)$file['MimeType'])throw new RuntimeException('SOURCE_OPTION_IMAGE_UNAVAILABLE');
        $actual=hash_file('sha256',$disk);
        if(!is_string($actual)||!hash_equals(strtolower((string)$file['ContentSha256']),strtolower($actual)))throw new RuntimeException('SOURCE_OPTION_IMAGE_UNAVAILABLE');
        $extension=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][(string)$file['MimeType']]??null;
        if(!$extension)throw new RuntimeException('SOURCE_OPTION_IMAGE_UNAVAILABLE');
        $storedName=time().'-'.bin2hex(random_bytes(18)).$extension;$target=sv_private_dir().DIRECTORY_SEPARATOR.$storedName;
        if(!copy($disk,$target))throw new RuntimeException('SOURCE_OPTION_IMAGE_UNAVAILABLE');
        try{$insert->execute([$targetCampaignId,$targetVersionId,'option_image',$storedName,$file['OriginalName'],$file['MimeType'],(int)$file['FileSize'],$file['ContentSha256'],$uploadedBy]);}
        catch(Throwable$error){@unlink($target);throw$error;}
        $copied[(int)$file['id']]=(int)$pdo->lastInsertId();
    }
    $update=$pdo->prepare("UPDATE SafetyVote_Options target JOIN SafetyVote_Questions targetQuestion ON targetQuestion.id=target.QuestionID AND targetQuestion.CampaignVersionID=? JOIN SafetyVote_Questions sourceQuestion ON sourceQuestion.CampaignVersionID=? AND sourceQuestion.QuestionCode=targetQuestion.QuestionCode JOIN SafetyVote_Options source ON source.QuestionID=sourceQuestion.id AND source.OptionCode=target.OptionCode SET target.FileID=? WHERE source.FileID=?");
    foreach($copied as$sourceFileId=>$targetFileId)$update->execute([$targetVersionId,$sourceVersionId,$targetFileId,$sourceFileId]);
    return count($copied);
}
function sv_duplicate_campaign_with_option_images(array$user,int$sourceId):void{
    $year=(int)(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y');
    for($attempt=0;$attempt<5;$attempt++){
        $pdo=db();$pdo->beginTransaction();
        try{
            $source=sv_campaign_row($sourceId,true);
            if(!$source||$source['Status']==='Voided'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Source campaign was not found.'],404);}
            $stmt=$pdo->prepare('SELECT MAX(CAST(SUBSTRING(CampaignCode,5,3) AS UNSIGNED)) sequenceNo FROM SafetyVote_Campaigns WHERE CampaignCode REGEXP ? FOR UPDATE');
            $stmt->execute(['^SHE-[0-9]{3}-'.$year.'$']);
            $campaignCode=sv_campaign_code((int)(($stmt->fetch()['sequenceNo']??0))+1,$year);
            if($campaignCode===null){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_CODE_EXHAUSTED','message'=>'The annual campaign code range is exhausted.'],409);}
            $actor=sv_actor($user);$title=mb_substr(trim((string)($source['TitleTh']?:$source['CampaignCode'])).' (สำเนา)',0,200);
            $pdo->prepare("INSERT INTO SafetyVote_Campaigns(CampaignCode,Status,OwnerEmployeeID,DiscoveryMode,ScheduledOpenAt,ScheduledCloseAt,CreatedBy,UpdatedBy) VALUES(?,'Draft',?,?,NULL,NULL,?,?)")->execute([$campaignCode,$actor,$source['DiscoveryMode']?:'eligible_only',$actor,$actor]);
            $id=(int)$pdo->lastInsertId();
            $stmt=$pdo->prepare("INSERT INTO SafetyVote_CampaignVersions(CampaignID,VersionNo,ContractVersion,TemplateKey,CampaignType,PrivacyMode,TitleTh,TitleEn,Summary,Description,RulesText,TimeZone,OpenAt,CloseAt,ResultVisibility,OfficialResultTopN,ResultReleasePolicy,PrivacyThreshold,MaxParticipationAttempts,LiveLeaderboardEnabled,LiveLeaderboardTopN,LiveLeaderboardScoreMode,LiveLeaderboardVisibility,LiveLeaderboardRefreshSeconds,LiveLeaderboardPrivacyThreshold,EditPolicy,ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,AllowAbstain,RandomizeOptions,Status,CreatedBy,UpdatedBy) SELECT ?,1,?,'config_copy',CampaignType,PrivacyMode,?,TitleEn,Summary,Description,RulesText,TimeZone,NULL,NULL,ResultVisibility,OfficialResultTopN,ResultReleasePolicy,PrivacyThreshold,MaxParticipationAttempts,LiveLeaderboardEnabled,LiveLeaderboardTopN,LiveLeaderboardScoreMode,LiveLeaderboardVisibility,LiveLeaderboardRefreshSeconds,LiveLeaderboardPrivacyThreshold,EditPolicy,ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,AllowAbstain,RandomizeOptions,'Draft',?,? FROM SafetyVote_CampaignVersions WHERE id=?");
            $stmt->execute([$id,SAFETY_VOTE_CONTRACT_VERSION,$title,$actor,$actor,$source['CurrentVersionID']]);
            $versionId=(int)$pdo->lastInsertId();
            $pdo->prepare('UPDATE SafetyVote_Campaigns SET CurrentVersionID=? WHERE id=?')->execute([$versionId,$id]);
            $pdo->prepare("INSERT INTO SafetyVote_Questions(CampaignVersionID,QuestionCode,QuestionType,Title,HelpText,IsRequired,MinSelections,MaxSelections,RandomizeOptions,AllowComment,ValidationJson,DisplayConditionJson,ResultVisibility,SortOrder,Status,CreatedBy,UpdatedBy) SELECT ?,QuestionCode,QuestionType,Title,HelpText,IsRequired,MinSelections,MaxSelections,RandomizeOptions,AllowComment,ValidationJson,DisplayConditionJson,ResultVisibility,SortOrder,Status,?,? FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active'")->execute([$versionId,$actor,$actor,$source['CurrentVersionID']]);
            $pdo->prepare("INSERT INTO SafetyVote_Options(QuestionID,OptionCode,Label,Description,ScoreValue,IsAbstain,FileID,SortOrder,Status,CreatedBy,UpdatedBy) SELECT nq.id,o.OptionCode,o.Label,o.Description,o.ScoreValue,o.IsAbstain,NULL,o.SortOrder,o.Status,?,? FROM SafetyVote_Options o JOIN SafetyVote_Questions oq ON oq.id=o.QuestionID JOIN SafetyVote_Questions nq ON nq.CampaignVersionID=? AND nq.QuestionCode=oq.QuestionCode WHERE oq.CampaignVersionID=? AND oq.Status='Active' AND o.Status='Active'")->execute([$actor,$actor,$versionId,$source['CurrentVersionID']]);
            $copiedOptionImages=sv_clone_option_images($pdo,(int)$source['CurrentVersionID'],$id,$versionId,$actor);
            $pdo->prepare("INSERT INTO SafetyVote_EligibilityRules(CampaignVersionID,RuleGroup,RuleOrder,Effect,AttributeKey,Operator,ValuesJson,Reason,IsActive,CreatedBy,UpdatedBy) SELECT ?,RuleGroup,RuleOrder,Effect,AttributeKey,Operator,ValuesJson,Reason,IsActive,?,? FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1 AND LOWER(AttributeKey) NOT IN ('employee','employee_id','employeeid')")->execute([$versionId,$actor,$actor,$source['CurrentVersionID']]);
            $pdo->commit();
            $excluded=['nonOptionFiles','media','frozenEligibility','eligibleVoters','roles','participation','ballots','answers','candidates','jury','results','certifications','notifications'];
            sv_audit($user,'SAFETY_VOTE_CAMPAIGN_DUPLICATE','SafetyVote_Campaign',(string)$id,'source='.$sourceId.'; code='.$campaignCode.'; optionImages='.$copiedOptionImages,['sourceCampaignId'=>$sourceId,'sourceCampaignCode'=>$source['CampaignCode'],'copiedOptionImages'=>$copiedOptionImages,'excluded'=>$excluded],$id,$versionId);
            json_response(['success'=>true,'data'=>array_merge(sv_campaign_row($id),['sourceCampaignId'=>$sourceId,'copiedOptionImages'=>$copiedOptionImages,'excluded'=>$excluded])],201);
        }catch(Throwable$error){
            if($pdo->inTransaction())$pdo->rollBack();
            if((string)$error->getCode()==='23000'&&$attempt<4)continue;
            if($error->getMessage()==='SOURCE_OPTION_IMAGE_UNAVAILABLE')json_response(['success'=>false,'code'=>'SOURCE_OPTION_IMAGE_UNAVAILABLE','message'=>'A source option image is unavailable.'],409);
            json_response(['success'=>false,'code'=>(string)$error->getCode()==='23000'?'CAMPAIGN_CODE_ALLOCATION_FAILED':'CAMPAIGN_DUPLICATE_FAILED','message'=>'Unable to duplicate campaign safely.'],500);
        }
    }
}

